<div class="mx-auto max-w-6xl space-y-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><h2 class="text-2xl font-bold text-gray-900">User accounts</h2><p class="text-sm text-gray-500">School Admins and Super Admins can create and reset user passwords. Super Admin accounts are protected.</p></div><button wire:click="create" class="rounded-lg bg-green-700 px-4 py-2 font-semibold text-white">Create user</button></div>@if($notice)<div class="rounded-lg bg-green-50 p-3 text-sm text-green-800">{{ $notice }}</div>@endif@if($showForm)<form wire:submit="save" class="grid gap-3 rounded-xl bg-white p-6 shadow-sm md:grid-cols-2"><input wire:model="name" placeholder="Full name" class="rounded-lg border px-3 py-2"><input wire:model="email" type="email" placeholder="Email" class="rounded-lg border px-3 py-2"><select wire:model="role" class="rounded-lg border px-3 py-2"><option value="">Select role</option>@foreach($roles as $item)<option value="{{ $item->name }}">{{ ucwords(str_replace('-', ' ', $item->name)) }}</option>@endforeach</select><input wire:model="password" type="password" placeholder="{{ $editingId ? 'New password (optional)' : 'Password' }}" class="rounded-lg border px-3 py-2"><div class="flex gap-2 md:col-span-2"><button type="submit" class="rounded-lg bg-green-700 px-4 py-2 font-semibold text-white">{{ $editingId ? 'Save / reset password' : 'Create account' }}</button><button type="button" wire:click="$set('showForm', false)" class="rounded-lg border px-4 py-2">Cancel</button></div></form>@endif<div class="overflow-x-auto rounded-xl bg-white shadow-sm"><table class="min-w-full divide-y text-left text-sm"><thead class="bg-gray-50 text-xs uppercase"><tr><th class="px-4 py-3">User</th><th class="px-4 py-3">Role</th><th class="px-4 py-3">Actions</th></tr></thead><tbody class="divide-y">@foreach($users as $user)<tr><td class="px-4 py-3"><strong>{{ $user->name }}</strong><p class="text-xs text-gray-500">{{ $user->email }}</p></td><td class="px-4 py-3">